// api/admin-whatsapp-router.ts
init_zod();
init_middleware();
init_connection();
init_schema2();
init_drizzle_orm();
var broadcastQueue = [];
var isBroadcasting = false;
var WHATSAPP_AUTH_TEMPORARILY_DISABLED2 = true;
var randomDelay = (min3, max3) => {
  const ms = Math.floor(Math.random() * (max3 - min3 + 1)) + min3;
  return new Promise((resolve2) => setTimeout(resolve2, ms));
};
function applySpintax(text2) {
  const spintaxRegex = /\{([^{}]+)\}/g;
  return text2.replace(spintaxRegex, (match2, optionsString) => {
    const options = optionsString.split("|");
    return options[Math.floor(Math.random() * options.length)];
  });
}
async function processBroadcastQueue() {
  if (isBroadcasting) return;
  isBroadcasting = true;
  while (broadcastQueue.length > 0) {
    const job = broadcastQueue.shift();
    if (job) {
      try {
        const finalMessage = applySpintax(job.text);
        await whatsappService.sendMessage(job.phone, finalMessage);
        console.log(`[WhatsApp Broadcast] Sent message to ${job.phone}`);
      } catch (err) {
        console.error(
          `[WhatsApp Broadcast] Failed to send message to ${job.phone}:`,
          err
        );
      }
      if (broadcastQueue.length > 0) {
        await randomDelay(12e4, 24e4);
      }
    }
  }
  isBroadcasting = false;
}
var adminWhatsappRouter = router({
  getStatus: adminProcedure.query(async () => {
    const statusInfo = whatsappService.getStatus();
    return {
      status: statusInfo.status,
      qrCode: statusInfo.qrCode,
      queueLength: broadcastQueue.length,
      isBroadcasting,
      phoneNumber: statusInfo.phoneNumber
    };
  }),
  startService: adminProcedure.mutation(async () => {
    await whatsappService.start();
    return { success: true, message: "\u062C\u0627\u0631\u064A \u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u062E\u062F\u0645\u0629..." };
  }),
  stopService: adminProcedure.mutation(async () => {
    await whatsappService.stop();
    return { success: true, message: "\u062A\u0645 \u0625\u064A\u0642\u0627\u0641 \u0627\u0644\u062E\u062F\u0645\u0629" };
  }),
  getSettings: adminProcedure.query(async () => {
    if (WHATSAPP_AUTH_TEMPORARILY_DISABLED2) {
      return { otpEnabled: false, temporarilyDisabled: true };
    }
    const setting = await db.query.systemSettings.findFirst({
      where: eq(systemSettings.key, "whatsapp_otp_enabled")
    });
    return { otpEnabled: setting?.value === "true" };
  }),
  toggleOtpVerification: adminProcedure.input(external_exports.object({ enabled: external_exports.boolean() })).mutation(async ({ input }) => {
    const existing = await db.query.systemSettings.findFirst({
      where: eq(systemSettings.key, "whatsapp_otp_enabled")
    });
    if (existing) {
      await db.update(systemSettings).set({ value: input.enabled ? "true" : "false" }).where(eq(systemSettings.key, "whatsapp_otp_enabled"));
    } else {
      await db.insert(systemSettings).values({
        key: "whatsapp_otp_enabled",
        value: input.enabled ? "true" : "false"
      });
    }
    return { success: true };
  }),
  sendDirectMessage: adminProcedure.input(
    external_exports.object({
      phone: external_exports.string().min(8),
      text: external_exports.string().min(1)
    })
  ).mutation(async ({ input }) => {
    try {
      await whatsappService.sendMessage(input.phone, input.text);
      return { success: true, message: "\u062A\u0645 \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0628\u0646\u062C\u0627\u062D" };
    } catch (err) {
      throw new Error(err.message || "\u0641\u0634\u0644 \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629");
    }
  }),
  getUsers: adminProcedure.query(async () => {
    const localList = await db.select({
      id: localUsers.id,
      name: localUsers.name,
      phone: localUsers.phone,
      email: localUsers.email,
      plan: localUsers.plan
    }).from(localUsers);
    const oauthList = await db.select({
      id: users.id,
      name: users.name,
      email: users.email,
      plan: users.plan
    }).from(users);
    const usersCombined = [
      ...localList.map((u3) => ({ ...u3, userType: "local" })),
      ...oauthList.map((u3) => ({ ...u3, phone: null, userType: "oauth" }))
    ];
    return usersCombined;
  }),
  broadcastMessage: adminProcedure.input(
    external_exports.object({
      text: external_exports.string().min(1)
    })
  ).mutation(async ({ input }) => {
    const users2 = await db.select({
      phone: localUsers.phone
    }).from(localUsers).where(and(isNotNull(localUsers.phone), ne(localUsers.phone, "")));
    if (users2.length === 0) {
      throw new Error("\u0644\u0627 \u064A\u0648\u062C\u062F \u0645\u0633\u062A\u062E\u062F\u0645\u064A\u0646 \u0628\u0623\u0631\u0642\u0627\u0645 \u0647\u0648\u0627\u062A\u0641 \u0645\u0633\u062C\u0644\u0629");
    }
    for (const u3 of users2) {
      if (u3.phone) {
        broadcastQueue.push({ phone: u3.phone, text: input.text });
      }
    }
    processBroadcastQueue();
    return {
      success: true,
      message: `\u062A\u0645\u062A \u0625\u0636\u0627\u0641\u0629 ${users2.length} \u0631\u0633\u0627\u0644\u0629 \u0625\u0644\u0649 \u0627\u0644\u0637\u0627\u0628\u0648\u0631 \u0648\u062C\u0627\u0631\u064A \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0628\u0628\u0637\u0621.`
    };
  }),
  clearQueue: adminProcedure.mutation(async () => {
    const cleared = broadcastQueue.length;
    broadcastQueue = [];
    return {
      success: true,
      message: `\u062A\u0645 \u062A\u0641\u0631\u064A\u063A \u0627\u0644\u0637\u0627\u0628\u0648\u0631 (\u0625\u0644\u063A\u0627\u0621 ${cleared} \u0631\u0633\u0627\u0644\u0629).`
    };
  })
});

